  // --- Screenshots (optional now: every section is drawn in code). Kept for later use. ---
  screenshots: {},

  // --- Features (icon = emoji shown in the card) -------------------------------------------
  features: [
    { icon: "🎞️", en: ["Scrub by hovering", "Move the pointer across any video tile to skim it. No opening, no waiting. GIFs, Lottie and Rive play on hover too."],
                  vi: ["Rê chuột là tua", "Lướt con trỏ qua ô video để xem nhanh, không cần mở, không phải chờ. GIF, Lottie và Rive cũng tự chạy khi rê chuột."] },
    { icon: "▶️", en: ["A player made for editors", "Frame stepping, timecode ↔ frames, QuickTime-style trim, a play queue and playlists. Arrange the control bar your way, cast to an Apple TV with AirPlay, keep a mini view on top with previous / next."],
                  vi: ["Player cho dân dựng phim", "Bước từng frame, timecode ↔ số frame, trim kiểu QuickTime, hàng chờ và playlist. Tự sắp xếp thanh điều khiển, phát lên Apple TV bằng AirPlay, mini view nổi trên cùng có nút clip trước / sau."] },
    { icon: "💬", en: ["Transcripts & search by speech", "Transcribe with macOS Speech (nothing to install on macOS 26), whisper.cpp or a cloud service. Then find a clip by what someone says in it."],
                  vi: ["Transcript & tìm theo lời nói", "Tạo transcript bằng macOS Speech (macOS 26 không cần cài gì), whisper.cpp hoặc dịch vụ cloud, rồi tìm clip theo câu ai đó nói trong đó."] },
    { icon: "✨", en: ["AI Review beside the video", "Let AI check the transcript line by line next to the playing clip. Click a suggestion to hear it, keep what's right."],
                  vi: ["AI Review cạnh video", "Để AI soát transcript từng dòng ngay cạnh clip đang phát. Bấm gợi ý để nghe lại, giữ chỗ đúng."] },
    { icon: "🔎", en: ["Advanced Search", "Duplicates, dates, sizes, accent-insensitive names. Or just say what you're looking for, in English or Vietnamese."],
                  vi: ["Advanced Search", "Tìm file trùng, theo ngày, dung lượng, tên không dấu. Hoặc nói luôn điều bạn cần tìm, bằng tiếng Anh hay tiếng Việt."] },
    { icon: "🧊", en: ["Previews for 3D & motion files", "Thumbnails for .blend, .c4d, .fbx, .obj, .usd, glTF, Lottie and Rive, plus a viewer where Rive files respond to your mouse."],
                  vi: ["Xem trước file 3D & motion", "Thumbnail cho .blend, .c4d, .fbx, .obj, .usd, glTF, Lottie, Rive, kèm cửa sổ xem, file Rive phản hồi theo chuột."] },
    { icon: "🌈", en: ["Folders with a mood", "Give each folder its own background: colours, gradients, images, GIF, video, Lottie or Rive, in up to six layers."],
                  vi: ["Thư mục có cá tính", "Mỗi thư mục một nền riêng: màu, gradient, ảnh, GIF, video, Lottie hoặc Rive, tối đa sáu lớp."] },
    { icon: "⚡️", en: ["Quick Actions", "Right-click to trim, compress, make a GIF, convert images, remove a background or create a PDF."],
                  vi: ["Quick Actions", "Chuột phải để cắt, nén, xuất GIF, đổi định dạng ảnh, xoá nền hay tạo PDF."] },
    { icon: "🗂️", en: ["Tabs, panes & tags", "Drag tabs into split panes, colour tags that sync with Finder, smart folders, Group By, filter chips by file type."],
                  vi: ["Tab, khung & tag", "Kéo tab thành các khung chia màn hình, tag màu đồng bộ với Finder, Smart Folder, Group By, chip lọc theo loại file."] },
    { icon: "🪟", en: ["macOS, Windows 11 or Linux style", "Light, Dark or Midnight in three looks: macOS, Windows 11 (with Windows shortcuts) or Linux GNOME Files, for people who switch between systems."],
                  vi: ["Kiểu macOS, Windows 11 hoặc Linux", "Sáng, Tối hay Midnight với ba kiểu: macOS, Windows 11 (kèm phím tắt kiểu Windows) hoặc Linux GNOME Files, cho ai dùng nhiều hệ điều hành."] },
    { icon: "☁️", en: ["Cloud folders, like Finder", "Dropbox, iCloud Drive, Google Drive and OneDrive show each file's sync status. Files that live only in the cloud show their thumbnail without being downloaded."],
                  vi: ["Thư mục cloud như Finder", "Dropbox, iCloud Drive, Google Drive và OneDrive hiện trạng thái đồng bộ của từng file. File chỉ nằm trên cloud vẫn có thumbnail mà không bị tải về."] },
    { icon: "📊", en: ["Media info that keeps up", "Duration, frame rate and resolution appear the moment new clips land, and a render that was still being written is read again once it's done."],
                  vi: ["Thông số media luôn mới", "Thời lượng, fps và độ phân giải hiện ngay khi clip mới vào thư mục; file render đang ghi dở sẽ được đọc lại khi xong."] },
    { icon: "🧭", en: ["Feels like Finder", "Rename right where the name is, Open With lists the same apps as Finder, Get Info on disks with a space bar, free space in the status bar, Add to Dock from the sidebar."],
                  vi: ["Quen tay như Finder", "Đổi tên ngay tại chỗ, Open With có đủ app như Finder, Get Info ổ đĩa kèm thanh dung lượng, dung lượng trống ở thanh trạng thái, Add to Dock từ sidebar."] },
    { icon: "🧩", en: ["No ffmpeg needed", "MOV, MP4, ProRes, HEVC, GIF and audio work out of the box. ffmpeg is optional, only for MKV, WebM and AVI."],
                  vi: ["Không cần ffmpeg", "MOV, MP4, ProRes, HEVC, GIF và nhạc chạy ngay. ffmpeg không bắt buộc, chỉ cần cho MKV, WebM, AVI."] },
    { icon: "🔒", en: ["Private by default", "Nothing leaves your computer. Only if you add your own API key does the part you choose go to that service."],
                  vi: ["Riêng tư mặc định", "Không gì rời khỏi máy bạn. Chỉ khi bạn tự nhập API key, phần bạn chọn mới được gửi tới dịch vụ đó."] },
  ],

