    "views.list":     { en: "List", vi: "List" },
    "views.list.d":   { en: "Expand folders in place, sort by duration or transcript, group by anything.", vi: "Mở thư mục con tại chỗ, sắp theo thời lượng hay transcript, nhóm theo bất cứ gì." },
    "views.grid":     { en: "Grid", vi: "Grid" },
    "views.grid.d":   { en: "Big thumbnails you can scrub. Lottie, Rive and 3D play right in the tile.", vi: "Thumbnail lớn tua được. Lottie, Rive và 3D chạy ngay trong ô." },
    "views.columns":  { en: "Columns", vi: "Columns" },
    "views.columns.d":{ en: "The classic, with connector lines you can style and spring-loaded folders.", vi: "Kiểu cổ điển, đường nối cột tuỳ chỉnh, thư mục bật mở khi kéo file qua." },
    "views.gallery":  { en: "Gallery", vi: "Gallery" },
    "views.gallery.d":{ en: "One big preview with a filmstrip. Rive files are interactive here.", vi: "Một khung xem lớn kèm dải ảnh. File Rive tương tác được ở đây." },
    "views.globe":    { en: "Globe", vi: "Globe" },
    "views.globe.d":  { en: "Your folder as a 3D sphere. Drag to spin it. Just because it's fun.", vi: "Thư mục thành quả cầu 3D. Kéo chuột để xoay. Đơn giản vì nó vui." },


    "feat.kicker":    { en: "Everything in one window", vi: "Tất cả trong một cửa sổ" },
    "feat.title":     { en: "Built for the files media people use every day.", vi: "Làm cho đúng những file dân media dùng mỗi ngày." },

    "mp.kicker":      { en: "Media player", vi: "Media player" },
    "mp.title":       { en: "Play, trim, compress. Queue up a whole folder.", vi: "Phát, cắt, nén. Xếp cả thư mục vào hàng chờ." },
    "mp.sub":         { en: "Select clips and press Return: they play one after another. Drag ≡ to change the order, trim with the yellow handles, compress without leaving the player.",
                        vi: "Chọn nhiều clip rồi bấm Return: chúng phát lần lượt. Kéo ≡ để đổi thứ tự, cắt bằng hai tay cầm vàng, nén ngay trong player." },
    "mp.p1.t":        { en: "Play queue", vi: "Hàng chờ phát" },
