    "spot.player.k":  { en: "Player + transcript", vi: "Player + transcript" },
    "spot.player.t":  { en: "Watch, read and fix, side by side.", vi: "Xem, đọc và sửa, ngay cạnh nhau." },
    "spot.player.d":  { en: "The transcript follows the video. Click a line to jump there, and let AI Review catch the typos.", vi: "Transcript chạy theo video. Bấm một dòng để nhảy tới đó, để AI Review bắt lỗi chính tả." },
    "spot.bg.k":      { en: "Folder backgrounds", vi: "Nền thư mục" },
    "spot.bg.t":      { en: "Make each project feel like itself.", vi: "Mỗi dự án một không khí riêng." },
    "spot.bg.d":      { en: "Press ⌘J and put a gradient, a video, Lottie or Rive behind your files. Try it below.", vi: "Bấm ⌘J để đặt gradient, video, Lottie hay Rive phía sau file. Thử ngay bên dưới." },
    "spot.sort.k":    { en: "Media columns", vi: "Cột thông số media" },
    "spot.sort.t":    { en: "Sort by what matters in a shot.", vi: "Sắp xếp theo đúng thông số của cảnh quay." },
    "spot.sort.d":    { en: "FPS, resolution, codec and duration are columns like any other. Click a header to line up every 60 fps clip, or find the one 4K HEVC file. Coming next: group by aspect ratio, so 1:1, 16:9, 4:5 and 9:16 cuts each get their own pile.",
                        vi: "FPS, độ phân giải, codec, thời lượng là những cột như mọi cột khác. Bấm tiêu đề cột để gom mọi clip 60 fps, hay tìm ra file 4K HEVC duy nhất. Sắp có: nhóm theo tỉ lệ khung hình, bản 1:1, 16:9, 4:5, 9:16 mỗi loại một nhóm riêng." },
    "spot.sort.d.out": { en: "FPS, resolution, codec and duration are columns like any other. Click a header to line up every 60 fps clip, or find the one 4K HEVC file. Group by aspect ratio and the 1:1, 16:9, 4:5 and 9:16 cuts each get their own pile.",
                        vi: "FPS, độ phân giải, codec, thời lượng là những cột như mọi cột khác. Bấm tiêu đề cột để gom mọi clip 60 fps, hay tìm ra file 4K HEVC duy nhất. Nhóm theo tỉ lệ khung hình, bản 1:1, 16:9, 4:5, 9:16 mỗi loại một nhóm riêng." },
