    "spot.filter.k":  { en: "Filters & tags", vi: "Lọc & tag" },
    "spot.filter.t":  { en: "One click to just the files you need.", vi: "Một cú bấm là chỉ còn file bạn cần." },
    "spot.filter.d":  { en: "Filter chips by file type sit above every folder; ⌘-click to pick several. Colour tags sync with Finder, so click a tag to see everything marked Client or Final.",
                        vi: "Chip lọc theo loại file nằm sẵn trên mọi thư mục, ⌘-bấm để chọn nhiều. Tag màu đồng bộ với Finder, bấm một tag để xem mọi file gắn Client hay Final." },
