    "spot.search.t":  { en: "Say it. Find it.", vi: "Nói ra. Tìm thấy." },
    "spot.search.d":  { en: "Press 🎙 and describe the file. AI turns it into search criteria for you.", vi: "Bấm 🎙 rồi tả file cần tìm. AI tự điền tiêu chí giúp bạn." },

    "new.kicker":     { en: "What's new", vi: "Có gì mới" },
    "new.title":      { en: "Release notes", vi: "Ghi chú phát hành" },
    "new.sub":        { en: "Every version up to the one you can download.", vi: "Mọi phiên bản tính đến bản bạn tải được." },
    "new.note":       { en: "", vi: "Ghi chú phát hành viết bằng tiếng Anh, giống trong app." },
